import{_ as r,C as a,c as s,o as i,a9 as l,G as t}from"./chunks/framework.BMko4Wr3.js";const P=JSON.parse('{"title":"拓展","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/LuckPerms"},{"title":"拓展","link":"/LuckPerms/how-to.install-extensions"}]},"headers":[],"relativePath":"LuckPerms/how-to.install-extensions.md","filePath":"LuckPerms/how-to.install-extensions.md"}'),c={name:"LuckPerms/how-to.install-extensions.md"};function d(h,e,u,p,m,_){const o=a("NolebaseGitContributors"),n=a("NolebaseGitChangelog");return i(),s("div",null,[e[0]||(e[0]=l('<h1 id="拓展" tabindex="-1">拓展 <a class="header-anchor" href="#拓展" aria-label="Permalink to &quot;拓展&quot;">​</a></h1><p>拓展是为插件“附加”功能的一种方式。拓展可以在 LuckPerms 运行的平台独立运作（如 Bukkit、Sponge 等），也可以用相同的方式在其他平台上俺咋混个。它们使用的是插件提供的本地 API。</p><p>通俗来讲，它们是“插件的插件” —— 听起来有些绕，有些烧脑 —— 但对我刚刚好！</p><h2 id="安装拓展" tabindex="-1">安装拓展 <a class="header-anchor" href="#安装拓展" aria-label="Permalink to &quot;安装拓展&quot;">​</a></h2><p>拓展一般为 <code>.jar</code> 格式的文件。安装步骤为：</p><ol><li>进入 <code>/LuckPerms/</code> 文件夹（<code>config.yml</code> 所在的地方）</li><li>创建一个叫 <code>extensions</code> 的文件夹</li><li>将拓展 <code>.jar</code> 文件放入该文件夹中</li><li>重启服务器。</li></ol><h2 id="官方拓展" tabindex="-1">官方拓展 <a class="header-anchor" href="#官方拓展" aria-label="Permalink to &quot;官方拓展&quot;">​</a></h2><h3 id="rest-api" tabindex="-1">REST API <a class="header-anchor" href="#rest-api" aria-label="Permalink to &quot;REST API&quot;">​</a></h3><p><a href="./developers.standalone-app-rest-api">见此</a>了解更多。😃</p><h3 id="弃用拓展" tabindex="-1">弃用拓展 <a class="header-anchor" href="#弃用拓展" aria-label="Permalink to &quot;弃用拓展&quot;">​</a></h3><p>下述的拓展是大约 6 年前发布的（截止 2025 年 6 月算），用于减轻从 LuckPerms v4 升级至 v5 的负担。我们认为用户已经花了足够长的时间去升级，因此现在弃用它们，并不再受到支持。</p><ul><li><a href="https://github.com/LuckPerms/extension-legacy-api" target="_blank" rel="noreferrer">extension-legacy-api</a></li><li><a href="https://github.com/LuckPerms/extension-default-assignments" target="_blank" rel="noreferrer">extension-default-assignments</a></li></ul>',12)),t(o),t(n)])}const b=r(c,[["render",d]]);export{P as __pageData,b as default};
